+		goto cleanup_free2;

 	if (cg_create(child2))
-		goto cleanup;
+		goto cleanup_parent2;

 	if (cg_read(child2, "cgroup.controllers", buf, sizeof(buf)))
-		goto cleanup;
+		goto cleanup_all;

 	if (!cg_read_strstr(child2, "cgroup.controllers", "memory"))
-		goto cleanup;
+		goto cleanup_all;

 	ret = KSFT_PASS;

-cleanup:
-	cg_destroy(child);
-	cg_destroy(parent);
-	free(parent);
-	free(child);
